            "path": "src/app/(chat)/assistant/_components/reply-view.tsx",
            "purpose": "Route-private presentation, unreused so not promoted into a ui/ segment"
          },
          {
            "path": "src/app/api/assistant-reply/route.ts",
            "purpose": "POST stream channel: decode/validate, authenticate, pre-commit status mapping, SSE headers, commit"
