            "purpose": "Worker contract: runAssistantReplyJob plus job outcome; consumer is the queue callback route"
          },
          {
            "path": "src/modules/assistant-reply/client.ts",
            "purpose": "Browser-safe API publishing useReplyStream; consumer is the assistant route segment"
